with cat as (
  select id, name from categories where game_id = 'truth-or-lie' and name = 'ไหวพริบ'
)
insert into questions (game_id, category_id, text, answer, explain)
select 'truth-or-lie', cat.id, v.text, v.answer, v.explain
from (values
    ('แมวมี 9 ชีวิต แปลว่าซื้อแมว 1 ตัว เท่ากับได้แมว 9 ตัวซ่อนอยู่ในร่างเดียวกัน', false, 'มั่ว! ''แมว 9 ชีวิต'' เป็นแค่สำนวนเปรียบเปรยว่าแมวรอดตายเก่ง ไม่ได้มีชีวิตจริง 9 ดวงซ่อนอยู่ ถ้าซื้อมา 1 ตัว ก็ได้แมว 1 ตัวเท่านั้นแหละ'),
    ('เพื่อนบอกว่า ''เดี๋ยวมา'' แล้วหายไป 3 ชั่วโมง แสดงว่าเขาโกหกตั้งแต่ต้น', false, 'มั่ว! อาจแค่ประเมินเวลาพลาดหรือเจอเหตุสุดวิสัยระหว่างทาง ไม่ได้แปลว่าตั้งใจโกหกตั้งแต่แรกเสมอไป (แต่ก็รอเก้อได้เหมือนกันแหละเนอะ)'),
    ('กดปุ่มปิดประตูลิฟต์รัวๆ หลายครั้งติดกัน จะทำให้ประตูปิดเร็วขึ้นกว่าเดิม', false, 'มั่ว! ลิฟต์ยุคใหม่ส่วนใหญ่ปิดการทำงานปุ่มปิดประตูสำหรับผู้โดยสารทั่วไปไปแล้ว (เหลือไว้ให้เจ้าหน้าที่ใช้จริงๆ) กดรัวแค่ไหนก็ไม่ได้เร็วขึ้น แค่ได้ระบายอารมณ์เฉยๆ'),
    ('เผลอกดไลก์รูปเก่าเพื่อนตอนไถฟีดย้อนหลังไปลึกมากๆ เขาจะไม่มีวันรู้เด็ดขาด', false, 'มั่ว! การแจ้งเตือนไลก์ขึ้นทันทีไม่ว่าโพสต์จะเก่าแค่ไหน เขารู้แน่นอนว่าคุณไถไปถึงไหนแล้ว 😅'),
    ('เอาช้อนโลหะเข้าไมโครเวฟพร้อมอาหาร เป็นเรื่องปลอดภัยดี เพราะช้อนไม่ใช่วัตถุไวไฟ', false, 'มั่ว! โลหะในไมโครเวฟทำให้เกิดประกายไฟและอาจทำเครื่องพังได้ เพราะคลื่นไมโครเวฟเหนี่ยวนำกระแสไฟฟ้าในโลหะ ไม่เกี่ยวกับไวไฟหรือไม่ไวไฟเลย'),
    ('เสียบชาร์จตอนแบตเหลือ 1% จะทำให้แบตฟื้นจาก 1% เป็น 100% ภายในไม่กี่วินาที', false, 'มั่ว! ยังไงก็ต้องใช้เวลาชาร์จตามปกติ ไม่มีมือถือเครื่องไหนฟื้นแบตแบบเวทมนตร์ได้ในพริบตา'),
    ('เสียงท้องร้องโกร๊กๆ ตอนหิว เป็นส่วนหนึ่งของระบบสื่อสารจริงๆ ระหว่างลำไส้กับสมอง', true, 'ถูก! เสียงท้องร้องเกิดจากกระเพาะและลำไส้บีบตัวตอนว่าง ซึ่งเป็นส่วนหนึ่งของระบบที่เรียกว่า gut-brain axis จริงๆ (แค่ไม่ได้คุยกันเป็นประโยคอย่างที่ล้อเล่นกันเฉยๆ)'),
    ('มือถือตกน้ำแล้วรีบเอาไปแช่ข้าวสารทันที จะช่วยให้แห้งสนิทและใช้งานได้เหมือนเดิม 100% เสมอ', false, 'มั่ว! ข้าวสารช่วยดูดความชื้นได้บ้าง แต่ไม่การันตีว่าจะกู้เครื่องกลับมาได้เหมือนเดิมเสมอไป วิธีที่แนะนำจริงๆ คือปิดเครื่องทันทีแล้วรีบส่งช่างดีกว่า'),
    ('เห็นแมวเดินตัดหน้าแล้วเกิดเรื่องซวยตามมา แปลว่าแมวเป็นต้นเหตุของเคราะห์ร้ายนั้นจริงๆ', false, 'มั่ว! เป็นความเชื่อโชคลางที่ไม่มีหลักฐานทางวิทยาศาสตร์รองรับเลย แมวแค่เดินผ่านไปตามทางของมันเฉยๆ ไม่ได้เกี่ยวอะไรด้วย'),
    ('กินลูกอมรสเปรี้ยวจี๊ดก่อนสอบ จะช่วยให้สมองตื่นตัวและจำเนื้อหาได้ดีขึ้นจริง เพราะความเปรี้ยวช็อกประสาท', false, 'มั่ว! ไม่มีหลักฐานทางวิทยาศาสตร์ว่าความเปรี้ยวช่วยเพิ่มความจำ อย่างมากก็แค่ทำให้ตาสว่างวูบหนึ่งจากรสชาติเท่านั้นเอง'),
    ('ปัดปิดแอปออกจากหน้าจอ Recent Apps บ่อยๆ จะทำให้มือถือแบตอึดขึ้นเสมอ', false, 'มั่ว! การปิดแอปบ่อยๆ อาจทำให้แอปต้องเปิดใหม่ตั้งแต่ต้นทุกครั้งซึ่งกินแบตมากกว่าปล่อยให้พักอยู่เบื้องหลังแบบ suspended เสียอีกในหลายกรณี'),
    ('มือถือที่โฆษณาว่า ''กันน้ำ'' สามารถเอาไปดำน้ำลึกแค่ไหนก็ได้แบบไม่จำกัด', false, 'มั่ว! การกันน้ำมีมาตรฐาน IP rating กำหนดความลึกและระยะเวลาที่ทนได้ชัดเจน ไม่ใช่กันน้ำได้แบบไม่มีขีดจำกัด เอาไปดำน้ำลึกเกินสเปกก็จอดเหมือนกัน'),
    ('ยืนอยู่หน้าไมโครเวฟตอนมันทำงาน จะโดนรังสีไมโครเวฟรั่วซึมจนเป็นอันตรายเสมอ', false, 'มั่ว! ไมโครเวฟที่ผลิตตามมาตรฐานมีการปิดผนึกและตัวล็อกประตูป้องกันรังสีรั่วไหลอยู่แล้ว ยืนดูขนมปังหมุนๆ ข้างหน้าได้อย่างปลอดภัยตามปกติ')
  ) as v(text, answer, explain)
cross join cat
where not exists (
  select 1 from questions q2
  where q2.game_id = 'truth-or-lie' and q2.text = v.text
);